 * @hidden N
 */
scwin.tx_fn_PrelistPageSearch = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_PrelistPageSearch"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_PrelistPageSearch", unresolved: "action:self_submit:tx_fn_PrelistPageSearch" };
};

/**
 * @method
 * @name selectBox
 * @description select Box 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.selectBox = function (ver) {
    const date = new Date();
    let year;
    let month;
    document.write("<option value=''>--- 선택 ---</option>");
    for (let i = 1; i < 13; i++) {
        if (ver === '0') {
            year = date.getFullYear();
            month = (date.getMonth() + 1) + "";
            if (month.length === 1) {
                month = "0" + month;
            }
            date.setMonth(date.getMonth() + 1);
            document.write("<option  value='" + (year + "" + month) + "'>" + year + "년" + month + "월" + "</option>");
        } else {
            if (ver === '1') {
                document.write("<option value='" + i + "' >" + i + "월" + "</option>");
            } else {
                document.write("<option value='" + year + "'>" + year + "년</option>");
            }
        }
    }
};

